import{_ as t,o as e,c as o,ag as l}from"./chunks/framework.CAXxHpAX.js";const s=JSON.parse('{"title":"炼气化神","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-炼气化神.md","filePath":"50-概念资料/dict-炼气化神.md","lastUpdated":1778040484000}'),r={name:"50-概念资料/dict-炼气化神.md"};function i(u,a,c,d,h,n){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="炼气化神" tabindex="-1">炼气化神 <a class="header-anchor" href="#炼气化神" aria-label="Permalink to &quot;炼气化神&quot;">​</a></h1><blockquote><p>传统：丹道</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>炼气化神是丹道&quot;三关&quot;中的第二关——在炼精化气的基础上，将真气进一步转化为更高层次的&quot;神&quot;（精神能量），使精神饱满、智慧增上。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;炼气化神就是气足了，慢慢转化为神。神是什么？就是精神、智慧、觉知的力量。&quot;</p></blockquote><blockquote><p>&quot;精满不思欲，气满不思食，神满不思睡。炼气化神到了深处，人的精神状态会变得很好。&quot;</p></blockquote><blockquote><p>&quot;抱元守一——先天的元神和元炁，不是割裂的，而是一体的。修炼到深处，神中有气，气中有神，分不开。&quot;</p></blockquote><h2 id="了空居士的独特观点" tabindex="-1">了空居士的独特观点 <a class="header-anchor" href="#了空居士的独特观点" aria-label="Permalink to &quot;了空居士的独特观点&quot;">​</a></h2><p>了空居士不把炼精化气、炼气化神、炼神还虚割裂成三个独立的阶段——它们是<strong>渐进的自然过程</strong>，不是你可以&quot;选择&quot;去炼哪一个的阶段。</p><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-炼精化气">炼精化气</a> — 第一关</li><li><a href="/50-概念资料/dict-炼神还虚">炼神还虚</a> — 第三关</li><li><a href="/50-概念资料/dict-形神俱妙">形神俱妙</a> — 炼气化神到极致的结果</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-性命双修">性命双修</a></li></ul>',14)])])}const _=t(r,[["render",i]]);export{s as __pageData,_ as default};
